<script lang="ts">
 import {onMount,onDestroy} from 'svelte';import {CompanySocialClient} from './company-social-client';import '../automations/automations.css';
 export let companyId:string;export let actorId:string;export let conversationId:string;export let postId:string;export let requestingBotId:string;export let accessSignal:AbortSignal;
 let client:CompanySocialClient|null=null,post:any=null,loading=true,busy=false,error='',consent=false,live=true;
 async function load(){if(!client||accessSignal.aborted)return;loading=true;error='';consent=false;try{const value=await client.post(postId,conversationId);if(!live||accessSignal.aborted)return;if(value.botId!==requestingBotId)throw Error('The requesting bot could not be verified.');post=value;}catch(cause){if(live)error=(cause as Error).message;}finally{if(live)loading=false;}}
 async function publish(){if(!client||busy||!post||!consent||!post.actions.canPublish||post.state!=='DRAFT'||accessSignal.aborted)return;const snapshot={revision:post.revision,hash:post.reviewHash};busy=true;error='';try{const result=await client.publishPost(postId,conversationId,snapshot.revision,snapshot.hash);if(!live||accessSignal.aborted)return;if(result.botId!==requestingBotId)throw Error('The post outcome scope could not be verified.');post=result;consent=false;}catch(cause){if(live){error=(cause as Error).message;consent=false;}}finally{if(live)busy=false;}}
 function revoked(){live=false;client?.close();post=null;consent=false;}
 onMount(()=>{if(!actorId||accessSignal.aborted)return;client=new CompanySocialClient(companyId,()=>localStorage.token||'',accessSignal);accessSignal.addEventListener('abort',revoked,{once:true});void load();});onDestroy(()=>{revoked();accessSignal?.removeEventListener('abort',revoked);});
</script>
<section class="starli-automations social-post" aria-label="Review social post"><div class="sa-heading"><h3>Review {post?.definition?.platform==='instagram'?'Instagram':'Facebook'} post</h3><button type="button" disabled={busy||loading} on:click={load}>Refresh</button></div>{#if loading}<p class="sa-muted" role="status">Checking the exact saved post…</p>{/if}{#if error}<p class="sa-error" role="alert">{error}</p>{/if}{#if post}<p class="sa-muted">Page: {post.definition.pageId}{#if post.definition.instagramAccountId} · Instagram: {post.definition.instagramAccountId}{/if}</p><div class="post-text">{post.definition.text}</div>{#if post.definition.mediaRef}<p class="sa-muted">Media reference: {typeof post.definition.mediaRef==='string'?post.definition.mediaRef:JSON.stringify(post.definition.mediaRef)}</p>{/if}<p class="sa-muted">Revision {post.revision} · {post.state.replaceAll('_',' ').toLowerCase()}</p>{#if post.state==='PUBLISHED'}<p class="sa-success" role="status">Published{post.receipt?.providerPostId?' · '+post.receipt.providerPostId:''}</p>{:else if ['UNCERTAIN','SENDING'].includes(post.state)}<p class="sa-warning">The provider outcome is not final. Refresh the saved receipt; do not submit another copy.</p>{:else if post.actions.canPublish&&post.state==='DRAFT'}<label class="consent"><input type="checkbox" bind:checked={consent} disabled={busy}/><span>I approve this exact text and destination for publication.</span></label><button class="sa-primary" type="button" disabled={!consent||busy} on:click={publish}>{busy?'Publishing…':'Publish this reviewed post'}</button>{:else}<p class="sa-warning">{post.gate==='INSTAGRAM_ONE_OFF_MEDIA_ADAPTER_REQUIRED'?'Instagram publishing is not available for this post until its owned-media adapter is enabled.':'Publishing is not enabled for this saved post or your current company permissions.'}</p>{/if}{/if}</section>
<style>.social-post{margin:16px 0;padding:18px;border:1px solid #dfe7f2;border-radius:12px;background:#fff;white-space:normal}.post-text{white-space:pre-wrap;overflow-wrap:anywhere;background:#f8faff;border:1px solid #e2e8f0;border-radius:8px;padding:16px;margin:14px 0;font-size:13px;line-height:1.7;color:#17233b}.consent{display:flex;align-items:flex-start;gap:10px;font-size:12px;line-height:1.7;margin:14px 0}.consent input{margin-top:4px;accent-color:#2563eb}</style>
